// getElementById przyjmuje SAM identyfikator, bez zadnego prefiksu -
// document.getElementById("subtitle"), NIE document.getElementById("#subtitle").
// querySelector natomiast zawsze oczekuje PELNEGO selektora CSS, wiec przy
// selekcji po id trzeba jawnie dopisac znak # - document.querySelector("#subtitle").
// Pominiecie # w querySelector sprawiloby, ze silnik szukalby znacznika
// o NAZWIE "subtitle" (jak <subtitle>), a nie elementu o id="subtitle".

const lista = document.getElementById("task-list");
const ostatnie = lista.lastElementChild;
console.log(ostatnie.textContent);
console.log(ostatnie.nextElementSibling === null);

// Gdy masz juz referencje do konkretnego elementu (np. produkt),
// nawigacja wzgledem niego (produkt.parentElement, produkt.nextElementSibling)
// jest prostsza i mniej podatna na bledy niz napisanie od nowa selektora
// CSS, ktory musialby precyzyjnie opisac POZYCJE tego elementu wzgledem
// calego dokumentu. Nawigacja "z perspektywy" juz znanego elementu jest
// zwiezlejsza i czytelniejsza.

function szukajPoId(baza, id) {
  return baza[id] ?? null;
}

const baza = { produkt1: { nazwa: "Laptop" }, produkt2: { nazwa: "Telefon" } };
console.log(szukajPoId(baza, "produkt1"));
console.log(szukajPoId(baza, "brak"));

// getElementById dziala jak wywolanie KONKRETNEJ osoby po imieniu i
// nazwisku - jednoznaczne, szybkie, zawsze jedna, konkretna osoba (lub
// nikt, jesli takiej osoby nie ma).
// querySelector dziala jak powiedzenie "pierwsza osoba w niebieskiej
// koszuli" - znajduje PIERWSZA pasujaca osobe, niezaleznie od tego,
// ile ich jest w tlumie.
// querySelectorAll dziala jak powiedzenie "wszyscy w niebieskich
// koszulach" - zbiera WSZYSTKIE pasujace osoby naraz, jako cala grupe.

const przezId = document.getElementById("search-input");
const przezSelektor = document.querySelector("#search-input");
console.log(przezId === przezSelektor);

// getElementById jest technicznie NAJSZYBSZA metoda, poniewaz przegladarka
// utrzymuje wewnetrzny, zoptymalizowany "skrot" do wyszukiwania elementow
// po atrybucie id (id musi byc unikalne w calym dokumencie).
// Jest jednak NAJMNIEJ elastyczna - dziala WYLACZNIE z id, w przeciwienstwie
// do querySelector/querySelectorAll, ktore przyjmuja DOWOLNY, prawidlowy
// selektor CSS (klase, atrybut, zagniezdzenie, kombinacje).

